import itertools
E=[('L','T'),('N','T'),('T','U'),('L','E')]
def anc(S):
  S=set(S)
  while True:
    n={a for a,b in E if b in S}-S
    if not n: return S
    S|=n
def dsep(X,Y,Z):
  A=anc(X|Y|Z); G={frozenset(e) for e in E if set(e)<=A}
  for m in A:
    for p,q in itertools.combinations([a for a,b in E if b==m and a in A],2): G.add(frozenset((p,q)))
  seen=set(X); st=list(X)
  while st:
    u=st.pop()
    for e in G:
      if u in e:
        v=next(iter(e-{u}))
        if v not in Z and v not in seen: seen.add(v); st.append(v)
  return not seen&Y
for o,(X,Y,Z) in zip('ABCD',[('L','N','U'),('E','U','T'),('E','N','U'),('L','U','E')]): print(o,dsep({X},{Y},{Z}))  # only B True

